// ============================================================================
// Testbench: tb_ch11_median3
// Project: Praat-style F0 Estimation on DE10-Standard FPGA
// Description:
//   Cycle-accurate and bit-exact verification of rtl/v3/ch11_median3.v
//   Compatible with iverilog -g2012 -Wall
//
// Verification protocol:
//   - Reads transaction vectors generated by verify_v3/ch11_twin.py
//   - Tests:
//       1. Hand example [120, 122, 244, 121, 0, 0] -> [120, 122, 122, 121, 0, 0]
//       2. Stalled transactions with random idle cycles
//       3. Edge cases N=1 and N=2
//       4. Single spikes (octave jumps/halvings) and double spikes
//       5. Unvoiced zero runs, isolated glitches and dropouts
//       6. Frame-level verification on clean and noisy golden WAV datasets
//   - 2-phase sampling convention:
//       * Inputs driven at @(negedge clk)
//       * Outputs sampled at @(posedge clk); #1
//   - Checks that total cycles read matches EXPECTED_CYCLES (1065 cycles)
//   - Never aborts early on errors; accumulates all comparison errors
//   - Prints "Total comparison errors: N" and [PASS] / [FAIL]
// ============================================================================

`timescale 1ns / 1ps

module tb_ch11_median3;

    localparam integer EXPECTED_CYCLES = 1065;

    // Clock generation (50 MHz, 20 ns period)
    reg clk = 0;
    always #10 clk = ~clk;

    // DUT inputs
    reg        rst_n;
    reg        in_valid;
    reg        in_first;
    reg        in_last;
    reg [15:0] in_f0;

    // DUT outputs
    wire        out_valid;
    wire        out_last;
    wire [15:0] out_f0;

    // Instantiate DUT
    ch11_median3 dut (
        .clk       (clk),
        .rst_n     (rst_n),
        .in_valid  (in_valid),
        .in_first  (in_first),
        .in_last   (in_last),
        .in_f0     (in_f0),
        .out_valid (out_valid),
        .out_last  (out_last),
        .out_f0    (out_f0)
    );

    // Testbench tracking variables
    integer stim_fd;
    integer exp_fd;
    integer cycle_idx;
    integer errors;
    integer valid_outputs;

    // Stimulus record variables
    integer stim_vld;
    integer stim_first;
    integer stim_last;
    integer stim_f0;

    // Expected record variables
    integer exp_vld;
    integer exp_last;
    integer exp_f0;

    initial begin
        rst_n         = 0;
        in_valid      = 0;
        in_first      = 0;
        in_last       = 0;
        in_f0         = 16'd0;
        cycle_idx     = 0;
        errors        = 0;
        valid_outputs = 0;

        // Open stimulus file
        stim_fd = $fopen("verify_v3/tb_ch11_median3_stim.txt", "r");
        if (stim_fd == 0) stim_fd = $fopen("tb_ch11_median3_stim.txt", "r");
        if (stim_fd == 0) begin
            $display("[FAIL] Cannot open tb_ch11_median3_stim.txt");
            $finish;
        end

        // Open expected file
        exp_fd = $fopen("verify_v3/tb_ch11_median3_expected.txt", "r");
        if (exp_fd == 0) exp_fd = $fopen("tb_ch11_median3_expected.txt", "r");
        if (exp_fd == 0) begin
            $display("[FAIL] Cannot open tb_ch11_median3_expected.txt");
            $finish;
        end

        $display("=== STARTING CH11 MEDIAN-3 UNIT VERIFICATION ===");

        // Apply reset for 2 cycles
        @(negedge clk);
        rst_n = 0;
        @(negedge clk);
        rst_n = 1;

        // Main cycle-by-cycle testing loop
        while ($fscanf(stim_fd, "%d %d %d %d\n",
                       stim_vld, stim_first, stim_last, stim_f0) == 4 &&
               $fscanf(exp_fd, "%d %d %d\n",
                       exp_vld, exp_last, exp_f0) == 3) begin

            // 1. Drive inputs during clock low phase
            in_valid = (stim_vld != 0) ? 1'b1 : 1'b0;
            in_first = (stim_first != 0) ? 1'b1 : 1'b0;
            in_last  = (stim_last != 0) ? 1'b1 : 1'b0;
            in_f0    = stim_f0[15:0];

            // 2. Sample registered outputs after positive edge + #1
            @(posedge clk);
            #1;

            if (out_valid !== ((exp_vld != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: out_valid mismatch DUT=%b EXP=%b",
                         cycle_idx, out_valid, exp_vld != 0);
                errors = errors + 1;
            end

            if (out_valid) begin
                valid_outputs = valid_outputs + 1;

                if (out_last !== ((exp_last != 0) ? 1'b1 : 1'b0)) begin
                    $display("[FAIL] Cycle %0d: out_last mismatch DUT=%b EXP=%b",
                             cycle_idx, out_last, exp_last != 0);
                    errors = errors + 1;
                end

                if (out_f0 !== exp_f0[15:0]) begin
                    $display("[FAIL] Cycle %0d: out_f0 mismatch DUT=%0d EXP=%0d",
                             cycle_idx, out_f0, exp_f0[15:0]);
                    errors = errors + 1;
                end
            end

            cycle_idx = cycle_idx + 1;
            @(negedge clk);
        end

        $fclose(stim_fd);
        $fclose(exp_fd);

        if (cycle_idx != EXPECTED_CYCLES) begin
            $display("[FAIL] Read %0d cycles, expected %0d", cycle_idx, EXPECTED_CYCLES);
            errors = errors + 1;
        end

        $display("=== SUMMARY: Simulated %0d cycles, %0d valid outputs verified ===",
                 cycle_idx, valid_outputs);
        $display("=== Total comparison errors: %0d ===", errors);

        if (errors == 0) begin
            $display("[PASS] All %0d cycles matched bit-for-bit with Python twin!", cycle_idx);
        end else begin
            $display("[FAIL] Verification encountered %0d errors!", errors);
        end

        $finish;
    end

endmodule
